      "y": 3422.4000549316406,
      "width": 360,
      "height": 340,
      "text": "HÌNH 3.7",
      "fontSize": 18,
      "colorTheme": "purple",
      "mode": "text",
      "brushColor": "#2563eb",
      "brushSize": 2,
